import java.lang.reflect.Type;
import java.util.HashMap;
import java.util.Map;
import java.util.NoSuchElementException;

final class ServiceRegistry {
    private final Map<Class<?>, Object> byClass = new HashMap<>();
    private final Map<Type, Object> byType = new HashMap<>();

    // Class<T> and T tied together: the compiler checks the pair
    <T> void register(Class<T> type, T impl) { byClass.put(type, impl); }

    <T> T get(Class<T> type) {
        Object impl = byClass.get(type);
        if (impl == null) throw new NoSuchElementException("no service for " + type.getSimpleName());
        return type.cast(impl);                                // checked
    }

    // generic services: a super type token supplies the full type
    <T> void registerTyped(TypeRef<T> type, T impl) { byType.put(type.type, impl); }

    @SuppressWarnings("unchecked")                              // safe: only registerTyped puts values in
    <T> T getTyped(TypeRef<T> type) { return (T) byType.get(type.type); }
}

